
'''
Provide functions to simplify the xpath got by the upgraded Access Bridge Explorer tool.
'''
import re

def _remove_square_brackets(contents):
    pattern = re.compile(r'\[.*?\]')
    cleaned_contents = re.sub(pattern, '', contents)
    return cleaned_contents

def _replace_between_slash_and_bracket(contents):
    pattern = re.compile(r'/(?P<content_between_slash_and_bracket>[^/\[]+)\[')
    replaced_contents = re.sub(pattern, '/*[', contents)
    return replaced_contents

def remove_roles(xpath):
    return  _replace_between_slash_and_bracket(xpath)

def remove_roles_in_between(xpath:str):
    if len(xpath) > 1:
        last= xpath.rfind('/')
        path = _replace_between_slash_and_bracket(xpath[1:last])
        return "/" + path + xpath[last:] # start from 2nd node to the next to the last one.
    return xpath

def remove_index_in_parent(xpath):
    path = _remove_square_brackets(xpath)
    return path


if __name__ == "__main__":
    # Given string with square brackets
    xpath = "/root pane/layered pane[@indexinparent=1]/panel[@indexinparent=6]/panel[@indexinparent=0]/panel[@indexinparent=0]/toggle button[@indexinparent=2]/panel[@indexinparent=0]/panel[@indexinparent=1]/label[@indexinparent=1, @name=Sessions]"

    # Remove content within square brackets
    cleaned_string = remove_index_in_parent(xpath)
    cleaned_string2 = remove_roles(xpath)
    cleaned_string3 = remove_roles_in_between(xpath)

    # Output the cleaned string
    print(cleaned_string)  #"/root pane/layered pane/panel/panel/panel/toggle button/panel/panel/label"
    print(cleaned_string2) #"/root pane/*[@indexinparent=1]/*[@indexinparent=6]/*[@indexinparent=0]/*[@indexinparent=0]/*[@indexinparent=2]/*[@indexinparent=0]/*[@indexinparent=1]/*[@indexinparent=1, @name=Sessions]"
    print(cleaned_string3) #"/root pane/*[@indexinparent=1]/*[@indexinparent=6]/*[@indexinparent=0]/*[@indexinparent=0]/*[@indexinparent=2]/*[@indexinparent=0]/*[@indexinparent=1]/*[@indexinparent=1, @name=Sessions]"